import { approve_reject_requested_assets } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
export default {
  props: {
    rejectDialog: Boolean,
    rowData: Object
  },
  data() {
    return {
      loading: false,
      reasonforRejection: ""
    };
  },
  watch: {
    rejectDialog: {
      async handler() {
        if (this.rejectDialog == true) {}
      },
      immediate: true
    }
  },
  methods: {
    close_dialog() {
      this.$emit("clicked", 0);
    },
    async reject_action() {
      const {
        valid
      } = await this.$refs.form.validate();
      if (valid) {
        this.loading = true;
        try {
          let result = await API.graphql(graphqlOperation(approve_reject_requested_assets, {
            input: {
              initiate_id: this.rowData.responeObj.initiate_id,
              approval_status: "REJECTED",
              asset_dispatch_comments: this.reasonforRejection
            }
          }));
          var response = JSON.parse(result.data.approve_reject_requested_assets);
          this.loading = false;
          if (response.Status == "SUCCESS") {
            this.$emit("successMsg", response.Message);
            this.$refs.form.reset();
            this.reasonforRejection = "";
          } else {
            this.loading = false;
            this.$emit("errorMsg", response.Message);
          }
        } catch (error) {
          this.$emit("errorMsg", error.errors[0].message);
          this.loading = false;
        }
      }
    }
  }
};
